const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const graph = Array.from({ length: n + 1 }, () => []);
const to = [], cap = [];
for (let i = 0; i < m; i++) {
  const u = tok[2 + 3 * i], v = tok[3 + 3 * i], c = tok[4 + 3 * i];
  graph[u].push(to.length); to.push(v); cap.push(c);
  graph[v].push(to.length); to.push(u); cap.push(0);
}
const S = 1, T = n;
const level = new Array(n + 1).fill(-1), it = new Array(n + 1).fill(0);
function bfs() {
  level.fill(-1);
  level[S] = 0;
  const q = [S];
  for (let h = 0; h < q.length; h++) {
    const v = q[h];
    for (const e of graph[v]) if (cap[e] > 0 && level[to[e]] < 0) { level[to[e]] = level[v] + 1; q.push(to[e]); }
  }
  return level[T] >= 0;
}
function dfs(v, f) {
  if (v === T) return f;
  while (it[v] < graph[v].length) {
    const e = graph[v][it[v]];
    if (cap[e] > 0 && level[to[e]] === level[v] + 1) {
      const d = dfs(to[e], Math.min(f, cap[e]));
      if (d > 0) { cap[e] -= d; cap[e ^ 1] += d; return d; }
    }
    it[v]++;
  }
  return 0;
}
let flow = 0;
while (bfs()) {
  it.fill(0);
  let f;
  while ((f = dfs(S, Infinity)) > 0) flow += f;
}
console.log(String(flow));

