import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] graph;
    static int[] to, level, it;
    static long[] cap;
    static int S, T;

    static boolean bfs(int n) {
        Arrays.fill(level, -1);
        level[S] = 0;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(S);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int e : graph[v]) if (cap[e] > 0 && level[to[e]] < 0) { level[to[e]] = level[v] + 1; q.add(to[e]); }
        }
        return level[T] >= 0;
    }

    static long dfs(int v, long f) {
        if (v == T) return f;
        while (it[v] < graph[v].size()) {
            int e = graph[v].get(it[v]);
            if (cap[e] > 0 && level[to[e]] == level[v] + 1) {
                long d = dfs(to[e], Math.min(f, cap[e]));
                if (d > 0) { cap[e] -= d; cap[e ^ 1] += d; return d; }
            }
            it[v]++;
        }
        return 0;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        graph = new List[n + 1];
        for (int i = 0; i <= n; i++) graph[i] = new ArrayList<>();
        to = new int[2 * m];
        cap = new long[2 * m];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            in.nextToken();
            long c = (long) in.nval;
            graph[u].add(2 * i); to[2 * i] = v; cap[2 * i] = c;
            graph[v].add(2 * i + 1); to[2 * i + 1] = u; cap[2 * i + 1] = 0;
        }
        S = 1;
        T = n;
        level = new int[n + 1];
        it = new int[n + 1];
        long flow = 0;
        while (bfs(n)) {
            Arrays.fill(it, 0);
            long f;
            while ((f = dfs(S, Long.MAX_VALUE)) > 0) flow += f;
        }
        System.out.println(flow);
    }
}

