#include <bits/stdc++.h>
using namespace std;

int n, m, S, T;
vector<vector<int>> graph;
vector<int> to_, level_, it_;
vector<long long> cap_;

bool bfs() {
    fill(level_.begin(), level_.end(), -1);
    level_[S] = 0;
    queue<int> q;
    q.push(S);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int e : graph[v]) if (cap_[e] > 0 && level_[to_[e]] < 0) { level_[to_[e]] = level_[v] + 1; q.push(to_[e]); }
    }
    return level_[T] >= 0;
}
long long dfs(int v, long long f) {
    if (v == T) return f;
    while (it_[v] < (int)graph[v].size()) {
        int e = graph[v][it_[v]];
        if (cap_[e] > 0 && level_[to_[e]] == level_[v] + 1) {
            long long d = dfs(to_[e], min(f, cap_[e]));
            if (d > 0) { cap_[e] -= d; cap_[e ^ 1] += d; return d; }
        }
        it_[v]++;
    }
    return 0;
}

int main() {
    scanf("%d %d", &n, &m);
    graph.assign(n + 1, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        long long c;
        scanf("%d %d %lld", &u, &v, &c);
        graph[u].push_back(to_.size()); to_.push_back(v); cap_.push_back(c);
        graph[v].push_back(to_.size()); to_.push_back(u); cap_.push_back(0);
    }
    S = 1; T = n;
    level_.assign(n + 1, -1);
    it_.assign(n + 1, 0);
    long long flow = 0;
    while (bfs()) {
        fill(it_.begin(), it_.end(), 0);
        long long f;
        while ((f = dfs(S, LLONG_MAX)) > 0) flow += f;
    }
    printf("%lld\n", flow);
    return 0;
}
